// Medical Terminology Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and using different terms from Practice Tests 1–5.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-6',
 event:'Medical Terminology',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'Which suffix names an instrument used to measure?','-meter',['-metry','-graph','-scope'],'A','A thermometer measures temperature. -metry is the process of measuring, -graph a recording instrument and -scope a viewing instrument.',EHR),
  q(WP,'What does the suffix -gram mean?','A record or picture',['A process of recording','An instrument for cutting','A surgical repair'],'B','An electrocardiogram is the record produced; -graphy is the process, -tome a cutting instrument and -plasty repair.',EHR),
  q(WP,'What does the suffix -esthesia mean?','Sensation or feeling',['Movement','Breathing','Sleep'],'C','Anesthesia is loss of sensation. Movement is -kinesia, breathing is -pnea and sleep is hypn/o or somn/o.',EHR),
  q(WP,'What does the suffix -philia mean?','Attraction to or affinity for',['Fear of a situation','Condition of the mind','Lack of strength'],'D','Hemophilia literally means affinity for blood. Fear is -phobia, mind is psych/o and lack of strength is -asthenia.',EHR),
  q(WP,'What does the suffix -lepsy mean?','Seizure',['Sleep','Speech','Weakness'],'A','Epilepsy and narcolepsy (a seizure of sleep) use -lepsy. Speech is -phasia and weakness is -asthenia or -paresis.',EHR),
  q(WP,'What does the suffix -ectomy mean?','Surgical removal',['Surgical incision','Surgical opening','Surgical fixation'],'B','Appendectomy is removal of the appendix. Incision is -tomy, a new opening is -stomy and fixation is -pexy.',EHR),
  q(WP,'What does the suffix -desis mean?','Binding or surgical fusion',['Destruction or breakdown','Crushing or grinding','Drooping or sagging'],'C','Arthrodesis is surgical fusion of a joint. Breakdown is -lysis, crushing -tripsy and drooping -ptosis.',EHR),
  q(WP,'What does the prefix micro- mean?','Small',['Large','Many','Few'],'D','A microscope views small objects. Large is macro- or mega-, many is poly- and few is oligo-.',EHR),
  q(WP,'What does the prefix meta- mean?','Change or beyond',['Before or ahead','Below or under','Self or own'],'A','Metastasis is spread beyond the original site. Before is pre-, below is sub- or hypo- and self is auto-.',EHR),
  q(WP,'What does the prefix ad- mean?','Toward',['Away from','Against','Without'],'B','Adduction moves a limb toward the midline. Away from is ab-, against is anti- and without is a- or an-.',EHR),
  q(WP,'What does the prefix ab- mean?','Away from',['Toward','Around','Within'],'C','Abduction moves a limb away from the midline; ad- means toward, circum- around and endo- within.',EHR),
  q(WP,'What does the combining form dextr/o mean?','Right side',['Left side','Both sides','Front side'],'D','Dextrocardia is a heart displaced to the right. Left is sinistr/o, both is ambi- or bi- and front is anter/o.',EHR),
  q(WP,'What does the combining form sinistr/o mean?','Left side',['Right side','Back side','Middle'],'A','Sinistr/o means left, as in sinistromanual (left-handed). Right is dextr/o, back is poster/o and middle is medi/o.',EHR),
  q(WP,'What does the combining form cerebr/o mean?','Cerebrum or brain',['Cerebellum only','Spinal cord','Skull'],'B','Cerebral means pertaining to the cerebrum. Cerebell/o is the cerebellum, myel/o the spinal cord and crani/o the skull.',EHR),
  q(WP,'What does the combining form cyst/o mean?','Urinary bladder or sac',['Cell','Kidney','Tissue'],'C','Cystitis is bladder inflammation. Cell is cyt/o, kidney nephr/o or ren/o and tissue hist/o.',EHR),
  q(WP,'What does the combining form glyc/o mean?','Sugar',['Fat','Protein','Salt'],'D','Glycosuria is sugar in the urine. Fat is lip/o or adip/o, protein is prote/o and salt is natr/o (sodium).',EHR),
  q(WP,'What does the combining form hydr/o mean?','Water',['Blood','Air','Stone'],'A','Hydrocephalus is fluid (water) in the head. Blood is hem/o, air pneum/o and stone lith/o.',EHR),
  q(WP,'What does the combining form mamm/o mean?','Breast',['Mother','Hand','Muscle'],'B','A mammogram is a breast X-ray. Mast/o also means breast; hand is chir/o or man/o and muscle is my/o.',EHR),
  q(WP,'What does the combining form ocul/o mean?','Eye',['Ear','Nose','Mouth'],'C','Ocular means pertaining to the eye, as do ophthalm/o and opt/o. Ear is ot/o, nose rhin/o and mouth or/o or stomat/o.',EHR),
  q(WP,'What does the combining form odont/o mean?','Tooth',['Gum','Jaw','Bone'],'D','An orthodontist straightens teeth. Gum is gingiv/o, jaw gnath/o and bone oste/o.',EHR),
  q(WP,'What does the combining form onc/o mean?','Tumor',['Nail','Ovary','Shoulder'],'A','Oncology is the study of tumors. Nail is onych/o, ovary oophor/o or ovari/o and shoulder om/o.',EHR),
  q(WP,'What does the combining form py/o mean?','Pus',['Fire','Pelvis','Stomach'],'B','Pyuria is pus in the urine. Fire or fever is pyr/o, renal pelvis pyel/o and stomach gastr/o.',EHR),
  q(WP,'What does the combining form tox/o mean?','Poison',['Tissue','Breath','Tongue'],'C','Toxicology is the study of poisons. Tissue is hist/o, breath spir/o and tongue gloss/o or lingu/o.',EHR),
  q(BODY,'Which abdominal region lies just below the ribs on the right or left side?','Hypochondriac region',['Hypogastric region','Umbilical region','Lumbar region'],'D','Hypo- (below) + chondr/o (cartilage): the hypochondriac regions lie below the rib cartilages; the hypogastric is below the stomach.',EHR),
  q(BODY,'A scrape that affects only the skin surface is described with which directional term?','Superficial',['Deep','Internal','Visceral'],'A','Superficial means toward or at the body surface; deep means farther from it. Visceral relates to internal organs.',EHR),
  q(BODY,'Which body cavity contains the urinary bladder and reproductive organs?','Pelvic cavity',['Cranial cavity','Thoracic cavity','Spinal cavity'],'B','The pelvic cavity lies below the abdominal cavity and holds the bladder, reproductive organs and end of the colon.',EHR),
  q(SKEL,'What is the common name for the sternum?','Breastbone',['Collarbone','Shoulder blade','Tailbone'],'C','The sternum is the breastbone. The clavicle is the collarbone, the scapula the shoulder blade and the coccyx the tailbone.',EHR),
  q(SKEL,'What is inflammation of a fluid-filled sac that cushions a joint called?','Bursitis',['Arthritis','Synovitis','Chondritis'],'D','Burs/o (bursa) + -itis. Arthritis is joint inflammation, synovitis inflammation of the joint lining and chondritis of cartilage.',EHR),
  q(MUS,'What is inflammation of muscle tissue called?','Myositis',['Myalgia','Myopathy','Myoma'],'A','My/o (muscle) + -itis (inflammation). Myalgia is muscle pain, myopathy muscle disease and myoma a muscle tumor.',EHR),
  q(MUS,'Which movement moves a limb in a circle, as in a windmill arm motion?','Circumduction',['Rotation','Supination','Eversion'],'B','Circumduction traces a cone-shaped circle; rotation turns a bone on its own axis, and eversion turns the sole outward.',EHR),
  q(RESP,'What is a deficient amount of oxygen reaching the body tissues called?','Hypoxia',['Hypercapnia','Hyperventilation','Hypopnea'],'C','Hypo- (deficient) + ox (oxygen) + -ia. Hypercapnia is excess CO2, and hypopnea is shallow breathing.',EHR),
  q(RESP,'What is inflammation of the throat called?','Pharyngitis',['Laryngitis','Tracheitis','Sinusitis'],'D','Pharyng/o (throat) + -itis. Laryngitis affects the voice box, tracheitis the windpipe and sinusitis the sinuses.',EHR),
  q(DIG,'What is inflammation of the appendix called?','Appendicitis',['Appendectomy','Diverticulitis','Ileitis'],'A','Appendic/o + -itis. Appendectomy is removal of the appendix; diverticulitis inflames pouches in the colon.',EHR),
  q(DIG,'What is a surgical opening from the colon to the outside of the abdomen called?','Colostomy',['Colectomy','Colotomy','Colonoscopy'],'B','Col/o + -stomy (new opening). Colectomy is removal, colotomy an incision and colonoscopy a visual examination.',EHR),
  q(DIG,'What is the medical term for a loss of appetite?','Anorexia',['Bulimia','Dysphagia','Polyphagia'],'C','An- (without) + -orexia (appetite). Polyphagia is excessive eating and dysphagia difficulty swallowing.',EHR),
  q(CV,'What is the death of heart muscle tissue caused by blocked blood flow called?','Myocardial infarction',['Myocarditis','Cardiomyopathy','Pericarditis'],'D','An infarction is tissue death from lack of blood; myocardial refers to heart muscle. This is commonly called a heart attack.',EHR),
  q(CV,'What is the narrowing of blood vessels called?','Vasoconstriction',['Vasodilation','Vasculitis','Varicosity'],'A','Vas/o (vessel) + -constriction narrows vessels and raises blood pressure; vasodilation widens them.',EHR),
  q(NERV,'What is loss of muscle coordination, often with an unsteady walk, called?','Ataxia',['Apraxia','Aphasia','Akinesia'],'B','A- (without) + -taxia (order, coordination). Apraxia is inability to perform learned movements, and akinesia is loss of movement.',EHR),
  q(NERV,'What is the medical term for ear pain?','Otalgia',['Otitis','Otorrhea','Otosclerosis'],'C','Ot/o (ear) + -algia (pain). Otitis is inflammation, otorrhea discharge and otosclerosis hardening of the middle ear bones.',EHR),
  q(ENDO,'Which gland is also called the hypophysis?','Pituitary gland',['Pineal gland','Thyroid gland','Adrenal gland'],'D','The hypophysis (pituitary) hangs below the brain and controls many other glands.',EHR),
  q(ENDO,'What is surgical removal of an adrenal gland called?','Adrenalectomy',['Adrenalitis','Adrenomegaly','Adrenopathy'],'A','Adrenal + -ectomy (removal). Adrenomegaly is enlargement and adrenopathy any adrenal disease.',EHR),
  q(ENDO,'Which condition causes high blood calcium from overactive glands behind the thyroid?','Hyperparathyroidism',['Hypoparathyroidism','Hyperthyroidism','Hypopituitarism'],'B','The parathyroid glands control calcium; overactivity raises calcium and can cause kidney stones and bone loss.',EHR),
  q(REPRO,'What is a newborn in the first 4 weeks of life called?','Neonate',['Toddler','Fetus','Embryo'],'C','Ne/o (new) + nat/o (birth). A neonate is a newborn up to 28 days old; a fetus is the developing baby before birth.',EHR),
  q(REPRO,'What is inflammation of the prostate gland called?','Prostatitis',['Orchitis','Epididymitis','Balanitis'],'D','Prostat/o + -itis. Orchitis affects the testis, epididymitis the epididymis and balanitis the glans penis.',EHR),
  q(REPRO,'What is an abnormally low number of sperm in semen called?','Oligospermia',['Azoospermia','Aspermia','Spermatocele'],'A','Olig/o (scanty) + sperm/o + -ia. Azoospermia is no sperm, and a spermatocele is a cyst of the epididymis.',EHR),
  q(INTEG,'What is a pressure injury of the skin from lying in one position too long called?','Decubitus ulcer',['Varicose ulcer','Peptic ulcer','Aphthous ulcer'],'B','Decubitus means lying down; these bedsores form over bony areas. Peptic ulcers are in the stomach and aphthous ulcers in the mouth.',EHR),
  q(INTEG,'What is the medical term for a common wart?','Verruca',['Vesicle','Macule','Keloid'],'C','A verruca is a wart caused by a virus. A vesicle is a small blister, a macule a flat spot and a keloid an overgrown scar.',EHR),
  q(INTEG,'What is a small, raised, fluid-filled blister on the skin called?','Vesicle',['Papule','Pustule','Nodule'],'D','A vesicle holds clear fluid; a papule is a small solid bump, a pustule holds pus and a nodule is a larger solid lump.',EHR),
  q(URIN,'What is the involuntary release of urine, especially bedwetting at night, called?','Enuresis',['Anuria','Nocturia','Urgency'],'A','Enuresis is involuntary urination, and nocturnal enuresis is bedwetting. Nocturia is waking at night to urinate.',EHR),
  q(URIN,'What is surgical removal of a kidney called?','Nephrectomy',['Nephrotomy','Nephropexy','Nephrostomy'],'B','Nephr/o (kidney) + -ectomy. Nephrotomy is an incision, nephropexy fixation and nephrostomy a new opening into the kidney.',EHR)
 ],9602)
};
